
/**
 * Generated by framework_parser.py for: Annex 18: The Safe Transport of Dangerous Goods by Air
 * This function injects a complete analysis panel into a target container.
 * @param {targetContainerId: string, getTranscriptText: function, onAnalyze: function} options
 * - targetContainerId: The ID of the DOM element where the panel's button should be injected.
 * - getTranscriptText: A function that returns the current transcript text to be analyzed.
 * - onAnalyze: A callback function that receives the full prompt package for AI processing.
 */
function injectAnnex18DangerousGoodsPanel(options) {
    const { targetContainerId, getTranscriptText, onAnalyze } = options;

    const uiText = {
        title: 'Annex 18: The Safe Transport of Dangerous Goods by Air Analysis',
        description: 'Analyze the current transcript for specific violations of the Annex 18: The Safe Transport of Dangerous Goods by Air. You can edit the prompt below.',
        buttonText: 'Analyze with Annex 18: The Safe Transport of Dangerous Goods by Air',
        defaultPrompt: `Analyze the provided transcript and identify behaviors that represent specific violations of the Annex 18: The Safe Transport of Dangerous Goods by Air.

KEY SECTIONS FOR ANALYSIS:
- **Dangerous Goods Classification**: The classification of an article or substance shall be in acc ordance with the provisions of the Technical Instructions. 
  Note.— The detailed definitions of the classes of dangerous goods are contained in the Technical Instructions. These classes identify the potential risks associated with the transport of dangerous goods by air and are those recommended by the United Nations Committee of Experts on the Transport of Dangerous Goods.     
_____________________ 



 
    
ANNEX 18  4-1 17/11/11...
- **Packing Standards**: .............................................................................................................................................  5-1 
 
 5.1 General re quirements ...............................................................................................................................  5-1 
 5.2 Packagings ............................................................................................................... ................................  5-1 
 
 
CHAPTER 6.    La b...
- **Labelling and Marking Compliance**: // Content for Labelling and Marking Compliance not automatically extracted. Please add manual description based on CHAPTER 6\.\s*Labelling and marking.
- **Shipper Duties**: // Content for Shipper Duties not automatically extracted. Please add manual description based on CHAPTER 7\.\s*Shipper’s responsibilities.
- **Operator Duties**: // Content for Operator Duties not automatically extracted. Please add manual description based on CHAPTER 8\.\s*Operator’s responsibilities.
- **Transport Limitations**: // Content for Transport Limitations not automatically extracted. Please add manual description based on CHAPTER 4\.\s*Limitation on the transport of dangerous goods by air.

FOR EACH POTENTIAL VIOLATION IDENTIFIED:
1. Quote the exact transcript excerpt (with timestamp and speaker).
2. Reference the specific principle, article or section of the framework that was violated.
3. Briefly analyze the nature and severity of the violation.

PROVIDE A FINAL SUMMARY: Does this pattern of behavior indicate that the responsible entity is systematically failing to comply with the Annex 18: The Safe Transport of Dangerous Goods by Air?`
    };

    const systemPrompt = 'You are a specialized legal and compliance analyst. Your task is to analyze dialogues strictly in the context of Annex 18: The Safe Transport of Dangerous Goods by Air, identifying specific violations with precise references. Your output must be structured, factual, and cited.';

    const container = document.getElementById(targetContainerId);
    if (!container) {
        console.error(`[Panel Injector] Target container with ID #${targetContainerId} not found.`);
        return;
    }

    // 1. Create the activation button
    const analysisButton = document.createElement('button');
    analysisButton.textContent = uiText.buttonText;
    analysisButton.className = 'btn btn-special-analysis'; // Add your own styling
    container.appendChild(analysisButton);

    // 2. Create the analysis panel (initially hidden)
    const panel = document.createElement('div');
    panel.className = 'analysis-panel'; // Style this class
    panel.style.display = 'none';
    panel.innerHTML = `
        <div class="panel-header">
            <h3>${uiText.title}</h3>
            <button class="close-btn">&times;</button>
        </div>
        <p>${uiText.description}</p>
        <textarea class="prompt-textarea">${uiText.defaultPrompt}</textarea>
        <button class="execute-analysis-btn">Run Analysis</button>
    `;
    document.body.appendChild(panel); // Append to body to act like a modal

    // 3. Add event listeners
    analysisButton.addEventListener('click', () => {
        panel.style.display = 'block';
    });

    panel.querySelector('.close-btn').addEventListener('click', () => {
        panel.style.display = 'none';
    });

    panel.querySelector('.execute-analysis-btn').addEventListener('click', () => {
        if (typeof onAnalyze !== 'function' || typeof getTranscriptText !== 'function') {
            alert('Analysis function not configured correctly.');
            return;
        }
        
        const userPrompt = panel.querySelector('.prompt-textarea').value;
        const transcriptText = getTranscriptText();

        // Package everything for the AI
        const analysisPackage = {
            system_prompt: systemPrompt,
            user_prompt: userPrompt,
            transcript: transcriptText,
            framework: 'Annex 18: The Safe Transport of Dangerous Goods by Air'
        };

        onAnalyze(analysisPackage);
        panel.style.display = 'none'; // Hide panel after starting analysis
    });

    console.log(`Panel for Annex 18: The Safe Transport of Dangerous Goods by Air injected and ready.`);
}
